NGINX: /etc/nginx/nginx.conf — фрагмент http{} (общий для всех сайтов):
server_tokens off;
client_max_body_size 64k;
client_body_timeout 10s;
client_header_timeout 10s;
keepalive_timeout 30s;

gzip on;
gzip_vary on;
gzip_min_length 1024;
gzip_comp_level 5;
gzip_proxied any;
gzip_types text/plain text/css application/json application/javascript application/xml application/xml+rss image/svg+xml;

# --- rate limiting зоны (10m ~ 160k IP) ---
limit_req_zone  $binary_remote_addr zone=general:10m  rate=10r/s;
limit_req_zone  $binary_remote_addr zone=forms:10m    rate=1r/s;
limit_req_zone  $binary_remote_addr zone=pay:10m      rate=20r/m;
limit_conn_zone $binary_remote_addr zone=perip:10m;
limit_req_status  429;
limit_conn_status 429;

# --- TLS общий ---
ssl_protocols TLSv1.2 TLSv1.3;
ssl_prefer_server_ciphers off;
ssl_session_cache shared:SSL:10m;
ssl_session_timeout 1d;
ssl_session_tickets off;
ssl_stapling on;
ssl_stapling_verify on;

NGINX: /etc/nginx/snippets/security-headers.conf — ПОДКЛЮЧАТЬ include В КАЖДОМ location, где есть свой add_header (иначе унаследованные заголовки исчезают):
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;
add_header X-Frame-Options "DENY" always;
add_header Permissions-Policy "geolocation=(), camera=(), microphone=(), payment=(), usb=(), interest-cohort=()" always;
add_header Cross-Origin-Opener-Policy "same-origin" always;
add_header Content-Security-Policy "default-src 'self'; base-uri 'self'; frame-ancestors 'none'; object-src 'none'; img-src 'self' data:; style-src 'self'; script-src 'self'; font-src 'self'; connect-src 'self'; form-action 'self' https://auth.robokassa.ru; upgrade-insecure-requests" always;
# HSTS: на старте max-age=300 без preload; поднять после проверки TLS
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

Примечание: interest-cohort устарел (FLoC свёрнут) — можно убрать, оставлен только для старых клиентов, вреда нет кроме warning в консоли Chrome.

NGINX: /etc/nginx/sites-available/dokumatika.ru — рабочий конфиг целиком:
upstream dokumatika_app {
    server 127.0.0.1:8081;
    keepalive 16;
}

server {
    listen 80;
    listen [::]:80;
    server_name dokumatika.ru www.dokumatika.ru;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://dokumatika.ru$request_uri; }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;                      # nginx >= 1.25.1; на старых: listen 443 ssl http2;
    server_name www.dokumatika.ru;
    ssl_certificate     /etc/letsencrypt/live/dokumatika.ru/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/dokumatika.ru/privkey.pem;
    return 301 https://dokumatika.ru$request_uri;
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name dokumatika.ru;

    ssl_certificate     /etc/letsencrypt/live/dokumatika.ru/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/dokumatika.ru/privkey.pem;
    ssl_trusted_certificate /etc/letsencrypt/live/dokumatika.ru/chain.pem;

    root /opt/dokumatika/static;
    limit_conn perip 10;

    # --- статика: версионируется через ?v=<hash>, кэш на год ---
    location ^~ /static/ {
        include snippets/security-headers.conf;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        access_log off;
        try_files $uri =404;
    }

    location = /robots.txt   { root /opt/dokumatika/static; access_log off; }
    location = /favicon.ico  { root /opt/dokumatika/static; access_log off; log_not_found off; }

    # --- ключевой файл IndexNow: отдаём как text/plain ---
    location ~ ^/[A-Za-z0-9-]{8,128}\.txt$ {
        root /opt/dokumatika/static;
        default_type text/plain;
        access_log off;
    }

    # --- health-check: без лимитов и без логов ---
    location = /healthz {
        proxy_pass http://dokumatika_app;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        access_log off;
    }

    # --- генерация документов: дорого по CPU ---
    location ~ ^/(generate|preview|download) {
        limit_req zone=forms burst=5 nodelay;
        include snippets/proxy.conf;
    }

    # --- инициация платежа ---
    location ~ ^/pay {
        limit_req zone=pay burst=5 nodelay;
        include snippets/proxy.conf;
    }

    # --- колбэк Robokassa: НЕ ограничивать по IP-rate, иначе потеряете платёж.
    #     Защита — проверка подписи в приложении (+ опционально allow-list IP).
    location = /robokassa/result {
        include snippets/proxy.conf;
        proxy_read_timeout 15s;
        access_log /var/log/nginx/dokumatika-pay.log;
    }

    location / {
        limit_req zone=general burst=20 nodelay;
        include snippets/proxy.conf;
    }
}

И /etc/nginx/snippets/proxy.conf:
proxy_pass http://dokumatika_app;
proxy_http_version 1.1;
proxy_set_header Connection "";
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_connect_timeout 3s;
proxy_send_timeout 30s;
proxy_read_timeout 30s;
proxy_buffering on;
include snippets/security-headers.conf;

verdicts.corrected:
Согласие в форме чекбокса допустимо: ч. 1 ст. 9 152-ФЗ разрешает давать согласие «в любой позволяющей подтвердить факт его получения форме, если иное не установлено федеральным законом». При этом с 1 сентября 2025 года ч. 1 ст. 9 (в ред. ФЗ от 24.06.2025 № 156-ФЗ) прямо требует, чтобы согласие было «оформлено отдельно от иных информации и (или) документов, которые подтверждает и (или) подписывает субъект персональных данных». Поэтому чекбокс должен:
1) быть самостоятельным элементом — не совмещённым с кнопкой отправки и не вшитым в оферту, пользовательское соглашение или общий чекбокс «принимаю условия» (формулировка «Нажимая кнопку, вы соглашаетесь…» с 01.09.2025 неправомерна) — прямое требование ч. 1 ст. 9;
2) быть не отмеченным по умолчанию — следует из требования ч. 1 ст. 9 о «конкретном, предметном, информированном, сознательном и однозначном» согласии (ред. ФЗ от 14.07.2022 № 266-ФЗ);
3) сопровождаться понятным текстом с указанием цели обработки и содержать ссылку на политику и/или полный текст согласия — требование информированности, ч. 1 ст. 9;
4) быть отдельным для каждой самостоятельной цели; при этом согласие на рекламную рассылку/звонки требуется отдельно не только по 152-ФЗ, но и в силу ч. 1 ст. 18 ФЗ «О рекламе» № 38-ФЗ (предварительное согласие абонента или адресата), с бременем доказывания на рекламораспространителе;
5) фиксироваться оператором так, чтобы можно было доказать факт получения согласия, — ч. 3 ст. 9 возлагает это бремя на оператора (конкретный состав логов законом не установлен).
Письменная форма согласия (либо электронный документ, подписанный ЭП, — они равнозначны в силу ч. 4 ст. 9) обязательна только в прямо предусмотренных законом случаях: ч. 1 ст. 11 (биометрические ПД), ч. 2 ст. 10 (специальные категории ПД), ч. 2 ст. 16 (решения на основании исключительно автоматизированной обработки). Трансграничная передача (ст. 12) письменного согласия не требует.
